const p = msg.payload || {};
const role = String(p.topic_role || '');
if (role === 'telemetry/slow') {
  flow.set('lf_last_slow_sensor_payload', p);
}
const slowPayload = flow.get('lf_last_slow_sensor_payload') || {};
const slowSensors = Array.isArray(slowPayload.sensors) ? slowPayload.sensors : [];
let rawOut = [null, null, null, null];
let normOut = [null, null, null, null];
let calOut = null;

if (role === 'telemetry/fast') {
  const fastSensors = p.sensors || {};
  const fastNorm = Array.isArray(fastSensors.norm) ? fastSensors.norm : [];
  for (let i = 0; i < 4; i++) {
    normOut[i] = { payload: Number(fastNorm[i] ?? 0), topic: 'norm' + i };
  }
  if (slowSensors.length) {
    for (let i = 0; i < 4; i++) {
      rawOut[i] = { payload: Number(slowSensors[i]?.raw ?? 0), topic: 'raw' + i };
    }
    calOut = { payload: slowPayload };
  }
} else {
  for (let i = 0; i < 4; i++) {
    const s = slowSensors[i] || {};
    rawOut[i] = { payload: Number(s.raw ?? 0), topic: 'raw' + i };
    normOut[i] = { payload: Number(s.norm ?? 0), topic: 'norm' + i };
  }
  calOut = { payload: p };
}

return [rawOut[0], rawOut[1], rawOut[2], rawOut[3], normOut[0], normOut[1], normOut[2], normOut[3], calOut];

const a = msg.payload.alarms || {};
const badCal = Number(a.bad_cal ?? a.sensor_bad_calibration ?? 0);
const saturated = Number(a.saturated ?? a.sensor_saturated ?? 0);
const weak = Number(a.weak ?? a.sensor_weak ?? 0);
const lineLost = Number(a.line_lost ?? 0);
msg.payload = `line_lost=${lineLost}, bad_cal=${badCal}, saturated=${saturated}, weak=${weak}`;
return msg;

const s=(msg.payload.severity||'').toLowerCase();
if(s==='warn'||s==='error'||s==='critical'){
  msg.payload = `[${msg.payload.severity}] ${msg.payload.code}: ${msg.payload.message}`;
  return msg;
}
return null;

const delayMs = 2500;
node.status({fill:'yellow',shape:'dot',text:'STOP ahora, export en 2.5 s'});
node.send({ payload: { cmd: 'stop' } });
setTimeout(() => {
    node.send({ payload: { cmd: 'dump_track' } });
    node.status({fill:'green',shape:'dot',text:'dump_track enviado'});
    setTimeout(() => node.status({}), 2000);
}, delayMs);
return null;

let p = Number(msg.payload?.line_pos);
if (Number.isFinite(p) && p !== 9999) {
    context.set('last', p);
    msg.payload = p;
    return msg;
}
msg.payload = context.get('last') ?? 0;
return msg;

const p = msg.payload || {};
const cal = p?.calibration || {};
const run = p?.run || {};
const out = new Array(18).fill(null);
out[0] = { payload: Number(p?.motors?.base_cmd ?? 0) };
out[1] = { payload: Number(p?.pid?.kp ?? 0) };
out[2] = { payload: Number(p?.pid?.ki ?? 0) };
out[3] = { payload: Number(p?.pid?.kd ?? 0) };
out[4] = { payload: Number(p?.perf?.fast_ms ?? 0) };
out[5] = { payload: Number(p?.perf?.slow_ms ?? 0) };
out[6] = { payload: Number(p?.sensor_summary?.lost_sum_threshold ?? p?.lost_sum_threshold ?? 0) };
out[7] = { payload: Number(p?.sensor_summary?.lost_max_threshold ?? p?.lost_max_threshold ?? 0) };
out[8] = { payload: Number(p?.ai?.enabled ?? 0) };
out[9] = { payload: Number(p?.ai?.model_enabled ?? 0) };
out[10] = { payload: Number(p?.ai?.blend ?? 0.65) };
out[11] = { payload: Number(cal?.sweep_pwm ?? 68) };
out[12] = { payload: Number(cal?.edge_target_pos ?? 560) };
out[13] = { payload: Number(cal?.align_kp ?? 0.22) };
out[14] = { payload: Number(cal?.align_ki ?? 0.0) };
out[15] = { payload: Number(cal?.align_kd ?? 0.07) };
out[16] = { payload: Number(run?.autonomous_window_enabled ?? 1) };
out[17] = { payload: Number(run?.autonomous_target_s ?? Math.round(Number(run?.autonomous_target_ms ?? 9000) / 1000)) };
return out;

const c = msg.payload.context || {};
const fmt = (v, n) => Number.isFinite(Number(v)) ? Number(v).toFixed(n) : '0';
msg.payload = `mode=${msg.payload.local_mode || 'unknown'}, cand=${msg.payload.local_mode_candidate || 'unknown'}, pos=${fmt(c.pos_norm,2)}, trend=${fmt(c.trend_pos_avg,3)}, curve=${fmt(c.curve_intensity,2)}, conf=${fmt(c.confidence_avg,2)}`;
return msg;

const recording = !!flow.get('dataset_recording');
const rows = Number(flow.get('dataset_rows') || 0);
if (typeof flow.get('dataset_label') === 'undefined') {
  flow.set('dataset_label', 'unknown');
}
if (typeof flow.get('dataset_manual_lap_count') === 'undefined') {
  flow.set('dataset_manual_lap_count', 0);
}
const label = String(flow.get('dataset_label') || 'unknown');
const sessionValue = String(flow.get('dataset_session') || '');
const session = sessionValue || 'none';
const lapCount = Number(flow.get('dataset_manual_lap_count') || 0);
return [
  { payload: `recording=${recording ? 1 : 0}, rows=${rows}, laps=${lapCount}, label=${label}, session=${session}, workflow=REC->NEW->START->LABEL/LAP->STOP` },
  { payload: `label=${label}` },
  { payload: `session=${session}` },
  { payload: `laps=${lapCount}` }
];

const recording = Number(msg.payload) !== 0;
flow.set('dataset_recording', recording);
const label = String(flow.get('dataset_label') || 'unknown');
let session = String(flow.get('dataset_session') || '');
if (recording && !session) {
  const now = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  session = `session_${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
  flow.set('dataset_session', session);
  flow.set('dataset_rows', 0);
  flow.set('dataset_manual_lap_count', 0);
  flow.set('dataset_manual_lap_mark_at', 0);
  flow.set('dataset_manual_lap_pending', 0);
}
const rows = Number(flow.get('dataset_rows') || 0);
const lapCount = Number(flow.get('dataset_manual_lap_count') || 0);
const status = `recording=${recording ? 1 : 0}, rows=${rows}, laps=${lapCount}, label=${label}, session=${session || 'none'}, workflow=REC->NEW->START->LABEL/LAP->STOP`;
return [
  { payload: status },
  { payload: `label=${label}` },
  { payload: `session=${session || 'none'}` },
  { payload: `laps=${lapCount}` }
];

const raw = (msg.payload && msg.payload.label) ? String(msg.payload.label) : String(msg.payload || 'unknown');
const allowed = new Set(['straight', 'straight_long', 'straight_short', 'left_soft', 'left_hard', 'right_soft', 'right_hard', 'recovery', 'unknown']);
const label = allowed.has(raw) ? raw : 'unknown';
flow.set('dataset_label', label);
flow.set('dataset_label_set_at', Date.now());
const recording = !!flow.get('dataset_recording');
const rows = Number(flow.get('dataset_rows') || 0);
const lapCount = Number(flow.get('dataset_manual_lap_count') || 0);
