];

const p = msg.payload || {};
const ai = p.ai || {};
const source = ai.source || p.ai_source || 'disabled';
const track = ai.track_mode || p.ai_track_mode || 'unknown';
const conf = Number(ai.confidence ?? p.confidence ?? 0);
const blend = Number(ai.blend ?? 0);
const bias = Number(ai.recovery_bias ?? 0);
const modelEnabled = Number(ai.model_enabled ?? 0);
const hookPresent = Number(ai.hook_present ?? 0);
msg.payload = `source=${source}, track=${track}, conf=${conf.toFixed(2)}, blend=${blend.toFixed(2)}, bias=${bias.toFixed(2)}, model=${modelEnabled}, hook=${hookPresent}`;
return msg;

const p = msg.payload || {};
const role = String(p.topic_role || '');
if (role === 'telemetry/slow') {
  flow.set('lf_slow_payload', p);
}
if (role === 'telemetry/fast') {
  flow.set('lf_fast_payload', p);
}

const fast = role === 'telemetry/fast' ? p : (flow.get('lf_fast_payload') || {});
const slow = role === 'telemetry/slow' ? p : (flow.get('lf_slow_payload') || {});
const recording = !!flow.get('dataset_recording');
let rows = Number(flow.get('dataset_rows') || 0);
const label = String(flow.get('dataset_label') || 'unknown');
const labelSetAtMs = Number(flow.get('dataset_label_set_at') || 0);
const labelAgeMs = labelSetAtMs > 0 ? Math.max(0, Date.now() - labelSetAtMs) : 0;
const session = String(flow.get('dataset_session') || '');
const hasSlow = Object.keys(slow).length > 0;
const datasetPath = 'C:\\Users\\bryan\\OneDrive\\Documentos\\PlatformIO\\Projects\\Seguidor IA\\telemetria\\dataset\\linefollower_ai_dataset.jsonl';
const manualLapCount = Number(flow.get('dataset_manual_lap_count') || 0);
const manualLapMarkAtMs = Number(flow.get('dataset_manual_lap_mark_at') || 0);
const manualLapMarkAgeMs = manualLapMarkAtMs > 0 ? Math.max(0, Date.now() - manualLapMarkAtMs) : 0;
let manualLapPending = Number(flow.get('dataset_manual_lap_pending') || 0) !== 0;

const ai = slow.ai || fast.ai || {};
const ctx = fast.context || slow.context || {};
const pidFast = fast.pid || {};
const pidSlow = slow.pid || {};
const motorsFast = fast.motors || {};
const motorsSlow = slow.motors || {};
const sensorsFast = fast.sensors || {};
const crossing = slow.crossing || {};
const run = slow.run || {};
const profile = slow.profile || {};
const norm = Array.isArray(sensorsFast.norm) ? sensorsFast.norm : [];
const slowSensors = Array.isArray(slow.sensors) ? slow.sensors : [];
const rawAt = (i) => Number(slowSensors[i]?.raw ?? 0);
const fmt = (v, n) => Number.isFinite(Number(v)) ? Number(v).toFixed(n) : '0';

let fileMsg = null;
let debugMsg = null;
if (role === 'telemetry/fast' && Object.keys(fast).length > 0) {
  const nextRowIndex = rows + 1;
  const row = {
    timestamp_unix_ms: Number(fast.timestamp_unix_ms ?? slow.timestamp_unix_ms ?? 0),
    timestamp_valid: Number(fast.timestamp_valid ?? slow.timestamp_valid ?? 0),
    uptime_ms: Number(fast.uptime_ms ?? slow.uptime_ms ?? 0),
    seq_fast: Number(fast.seq ?? 0),
    seq_slow: Number(slow.seq ?? 0),
    state: String(fast.state ?? slow.state ?? ''),
    drive_profile: String(fast.profile ?? profile.name ?? 'normal'),
    local_mode: String(fast.local_mode ?? slow.local_mode ?? ''),
    local_mode_candidate: String(fast.local_mode_candidate ?? slow.local_mode_candidate ?? ''),
    ai_source: String(ai.source ?? fast.ai_source ?? 'disabled'),
    ai_track_mode: String(ai.track_mode ?? fast.ai_track_mode ?? ''),
    ai_confidence: Number(ai.confidence ?? fast.ai_confidence ?? 0),
    ai_blend: Number(ai.blend ?? fast.ai_blend ?? 0),
    ai_speed_factor: Number(ai.speed_factor ?? fast.ai_speed_factor ?? 0),
    ai_kp_scale: Number(ai.kp_scale ?? fast.ai_kp_scale ?? 0),
    ai_ki_scale: Number(ai.ki_scale ?? fast.ai_ki_scale ?? 0),
    ai_kd_scale: Number(ai.kd_scale ?? fast.ai_kd_scale ?? 0),
    ai_pivot_threshold: Number(ai.pivot_threshold ?? fast.ai_pivot_threshold ?? 0),
    ai_pivot_cap: Number(ai.pivot_cap ?? fast.ai_pivot_cap ?? 0),
    ai_recovery_bias: Number(ai.recovery_bias ?? fast.ai_recovery_bias ?? 0),
    intersection_active: Number(fast.intersection_active ?? crossing.active ?? 0),
    intersection_score: Number(fast.intersection_score ?? crossing.score ?? 0),
    run_elapsed_ms: Number(fast.run_elapsed_ms ?? run.elapsed_ms ?? 0),
    run_lap_estimate: Number(fast.lap_estimate ?? run.lap_estimate ?? 0),
    run_intersection_count: Number(fast.run_intersection_count ?? run.intersection_count ?? 0),
    dataset_label: label,
    dataset_label_valid: label !== 'unknown' ? 1 : 0,
    dataset_label_set_at_ms: labelSetAtMs,
    dataset_label_age_ms: labelAgeMs,
    dataset_session: session,
    dataset_row_index: nextRowIndex,
    dataset_manual_lap_count: manualLapCount,
    dataset_manual_lap_marked: manualLapPending ? 1 : 0,
    dataset_manual_lap_mark_at_ms: manualLapMarkAtMs,
    dataset_manual_lap_mark_age_ms: manualLapMarkAgeMs,
    line_pos: Number(fast.line_pos ?? slow.line_pos ?? 0),
    line_lost: Number(fast.line_lost ?? slow.line_lost ?? 0),
    lost_ms: Number(fast.lost_ms ?? slow.lost_ms ?? 0),
    last_dir: String(fast.last_dir ?? slow.last_dir ?? ''),
    balance_lr: Number(fast.balance_lr ?? slow.balance_lr ?? 0),
    confidence_fast: Number(fast.confidence ?? 0),
    confidence_avg: Number(fast.confidence_avg ?? ctx.confidence_avg ?? slow.confidence ?? fast.confidence ?? 0),
    sensor_sum: Number(sensorsFast.sum ?? 0),
    sensor_max: Number(sensorsFast.max ?? 0),
    norm0: Number(norm[0] ?? 0),
    norm1: Number(norm[1] ?? 0),
    norm2: Number(norm[2] ?? 0),
    norm3: Number(norm[3] ?? 0),
    raw0: rawAt(0),
    raw1: rawAt(1),
    raw2: rawAt(2),
    raw3: rawAt(3),
    pos_norm: Number(fast.pos_norm ?? ctx.pos_norm ?? 0),
    trend_pos: Number(fast.trend_pos ?? ctx.trend_pos ?? 0),
    trend_pos_avg: Number(fast.trend_pos_avg ?? ctx.trend_pos_avg ?? 0),
    curve_intensity: Number(fast.curve_intensity ?? ctx.curve_intensity ?? 0),
    pid_error: Number(pidFast.error ?? pidSlow.error ?? 0),
    pid_integral: Number(pidFast.integral ?? pidSlow.integral ?? 0),
    pid_d_filt: Number(pidFast.d_filt ?? pidSlow.d_filt ?? 0),
    pid_correction: Number(pidFast.correction ?? pidSlow.correction ?? 0),
    motor_a_pwm: Number(motorsFast.a_pwm ?? motorsSlow.a_pwm ?? 0),
    motor_b_pwm: Number(motorsFast.b_pwm ?? motorsSlow.b_pwm ?? 0),
    base_eff: Number(motorsFast.base_eff ?? motorsSlow.adaptive_base_cmd ?? 0),
    dominant_sensor: String(fast.dominant_sensor ?? slow.dominant_sensor ?? '')
  };

  if (recording) {
    rows = nextRowIndex;
    flow.set('dataset_rows', rows);
    fileMsg = { payload: JSON.stringify(row), filename: datasetPath };
    debugMsg = { payload: row };
    if (manualLapPending) {
      flow.set('dataset_manual_lap_pending', 0);
      manualLapPending = false;
    }
  }
}

const source = String(ai.source ?? fast.ai_source ?? 'disabled');
const mode = String(ai.track_mode ?? fast.ai_track_mode ?? fast.local_mode ?? slow.local_mode ?? 'unknown');
const conf = Number(ai.confidence ?? fast.confidence ?? 0);
const summary = 'recording=' + (recording ? 1 : 0) + ', rows=' + rows + ', laps=' + manualLapCount + ', label=' + label + ', label_age_ms=' + labelAgeMs + ', session=' + (session || 'none') + ', slow=' + (hasSlow ? 1 : 0) + ', src=' + source + ', mode=' + mode + ', conf=' + fmt(conf, 2) + ', capture=manual_directional';
return [fileMsg, { payload: summary }, debugMsg];

const minMs = 200;
const now = Date.now();
const last = Number(context.get('last_ui_ms') || 0);
if ((now - last) < minMs) return null;
context.set('last_ui_ms', now);
return msg;

const p = msg.payload || {};
const profile = p.profile || {};
const crossing = p.crossing || {};
const run = p.run || {};
const track = p.track || {};
const fmtNum = (v, d = 2) => Number.isFinite(Number(v)) ? Number(v).toFixed(d) : '0';
const fmtMs = (value) => {
  const ms = Number(value || 0);
  if (!ms) return 'n/a';
  const totalSec = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSec / 60);
  const seconds = totalSec % 60;
  const millis = ms % 1000;
  return `${minutes}:${String(seconds).padStart(2, '0')}.${String(millis).padStart(3, '0')}`;
};
const autoEnabled = Number(run.autonomous_window_enabled ?? 1);
const autoTargetMs = Number(run.autonomous_target_ms ?? 9000);
const profileText = `perfil=${String(profile.name || 'normal')}, speed=${Number(profile.base_speed ?? p?.motors?.base_cmd ?? 0)}, blend=${fmtNum(profile.ai_blend ?? p?.ai?.blend ?? 0.65)}`;
const crossingText = `active=${Number(crossing.active ?? 0)}, score=${fmtNum(crossing.score ?? 0)}, dir=${String(crossing.preferred_dir || 'none')}, cruces=${Number(crossing.count ?? 0)}, marker=${Number(crossing.marker_detected ?? 0)}`;
const runText = `active=${Number(run.active ?? 0)}, elapsed=${fmtMs(run.elapsed_ms)}, auto_window=${autoEnabled}, target=${fmtMs(autoTargetMs)}, auto_run=${Number(run.autonomous_mode ?? 0)}, auto_elapsed=${fmtMs(run.autonomous_elapsed_ms)}, samples=${Number(run.buffered_samples ?? 0)}, lost=${Number(run.line_lost_count ?? 0)}, cruces=${Number(run.intersection_count ?? 0)}, laps=${Number(run.lap_estimate ?? 0)}, best=${fmtMs(run.best_lap_ms)}`;
const trackText = `ready=${Number(track.ready ?? 0)}, publishing=${Number(track.publishing ?? 0)}, samples=${Number(track.samples ?? 0)}/${Number(track.capacity ?? 0)}, run_id=${Number(track.run_id ?? 0)} | flujo: START -> pista -> STOP -> EXPORTAR`;
return [{ payload: profileText }, { payload: crossingText }, { payload: runText }, { payload: trackText }];
